		DELETE FROM BOK_VOUCH_DETAIL C
		WHERE 
            EXISTS(
            SELECT 1  
            FROM BOK_VOUCH_MAIN A, BOK_BATCH_TASK_TODO B
            WHERE  
              A.VOUCH_NUM = C.VOUCH_NUM
              AND B.BOOKSET_ID =  A.BOOKSET_ID
              AND A.BOOK_DATE >= B.BOOK_DATE
              AND B.SEQ_NO = #{seqNo}
              AND B.BOOKSET_DATE = #{BOOKSET_DATE}
              AND B.TASK_ID = #{taskId}
              AND A.BOOK_TYPE != '03'
              AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
            )

		DELETE FROM BOK_VOUCH_REL C
		WHERE 
			EXISTS(
            SELECT 1  
            FROM BOK_VOUCH_MAIN A, BOK_BATCH_TASK_TODO B
            WHERE  
              A.VOUCH_NUM = C.VOUCH_NUM
              AND B.BOOKSET_ID =  A.BOOKSET_ID
              AND A.BOOK_DATE >= B.BOOK_DATE
              AND B.SEQ_NO = #{seqNo}
              AND B.BOOKSET_DATE = #{BOOKSET_DATE}
              AND B.TASK_ID = #{taskId}
              AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
            )

		DELETE FROM BOK_VOUCH_MAIN A
		WHERE 
            EXISTS(
            SELECT 1  
            FROM BOK_BATCH_TASK_TODO B
            WHERE  
              B.BOOKSET_ID =  A.BOOKSET_ID
              AND B.SEQ_NO = #{seqNo}
              AND B.BOOKSET_DATE = #{BOOKSET_DATE}
              AND B.TASK_ID = #{taskId}
              AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
            )
            AND A.BOOK_DATE >= #{BOOKSET_DATE}
            AND A.BOOK_TYPE != '03'

